from datetime import datetime, timezone
from fastapi import APIRouter
from fastapi.responses import HTMLResponse
from app.services.registry import registry
from app.services.governance import governance
from app.services.office import office
router=APIRouter()
def _activity(a,c,s):
    if s=='DISABLED': return 'Desativado pelo Owner'
    m={'agent-01':['Orquestrando o ciclo','Avaliando tarefas da equipa','Verificando lacunas de capacidade'],'agent-02':['A recolher dados de mercado','A comparar pares e timeframes','A preparar observações para Risk'],'agent-03':['A avaliar risco','A verificar exposição e limites','A validar sinais recebidos'],'agent-04':['Executor autorizado — aguardando ordem','A verificar permissões','Pronto para ciclo de execução']}
    v=m.get(a,['Aguardando tarefa']); return v[c%len(v)]
def state_data():
    now=datetime.now(timezone.utc); c=int(now.timestamp()//4); arr=[]
    for x in registry.list_agents():
        ui='LOCKED' if x['status']=='DISABLED' else ('IDLE' if c%7==0 and x['id']=='agent-03' else 'WORKING')
        arr.append({**x,'ui_status':ui,'activity':_activity(x['id'],c,x['status']),'last_tick':now.isoformat()})
    return {'office':{'total_agents':len(arr),'working':sum(x['ui_status']=='WORKING' for x in arr),'idle':sum(x['ui_status']=='IDLE' for x in arr),'locked':sum(x['ui_status']=='LOCKED' for x in arr)},'agents':arr,'pending_requests':len([r for r in governance.list_requests() if r['status']=='PENDING']),'events':registry.events(),'server_time':now.isoformat(),'broker':office.broker}
@router.get('/state')
def state(): return state_data()
@router.get('',response_class=HTMLResponse)
def dashboard(): return HTML
HTML=r'''<!doctype html><html lang="pt-PT"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>AI Financial Office</title><style>
:root{--bg:#06090e;--p:#0d141e;--p2:#111b27;--l:#263447;--t:#eef4fb;--m:#8c9bad;--c:#63d7f5;--g:#43d483;--a:#f2be55;--r:#ff6d72}*{box-sizing:border-box}body{margin:0;background:radial-gradient(circle at 50% -10%,#17283e 0,#06090e 45%);color:var(--t);font:14px/1.45 Inter,system-ui,sans-serif}.shell{max-width:1500px;margin:auto;padding:22px}.top{display:flex;justify-content:space-between;gap:15px}.ey{color:var(--c);font-size:11px;font-weight:900;letter-spacing:.14em;text-transform:uppercase}.title{font-size:30px;font-weight:900;margin:4px 0}.muted{color:var(--m);font-size:12px}.online{border:1px solid #1d523e;background:#0b1a15;color:#a8f1c7;border-radius:999px;padding:8px 12px;font-weight:800}.dot{display:inline-block;width:7px;height:7px;background:var(--g);border-radius:50%;margin-right:7px}.nav{display:flex;gap:7px;flex-wrap:wrap;border-bottom:1px solid var(--l);margin:18px 0;padding-bottom:10px}.nav button{background:transparent;border:1px solid transparent;color:#9cacbf;padding:9px 12px;border-radius:9px;font-weight:800;cursor:pointer}.nav button.active,.nav button:hover{background:#111c29;border-color:#304156;color:#fff}.view{display:none}.view.active{display:block}.metrics{display:grid;grid-template-columns:repeat(4,1fr);gap:12px;margin-bottom:15px}.metric,.card,.panel{background:rgba(13,20,30,.96);border:1px solid var(--l);border-radius:14px}.metric{padding:15px}.label{font-size:10px;color:var(--m)}.value{font-size:28px;font-weight:900}.layout{display:grid;grid-template-columns:1.7fr .8fr;gap:15px}.ph{padding:14px 16px;border-bottom:1px solid var(--l);display:flex;justify-content:space-between}.office{padding:14px;display:grid;grid-template-columns:repeat(2,1fr);gap:12px}.desk{background:linear-gradient(145deg,#121c29,#0a1119);border:1px solid #2a3a4e;border-radius:13px;padding:14px;position:relative}.desk:after{content:"";position:absolute;left:0;right:0;bottom:0;height:3px;background:#263447}.working:after{background:var(--g)}.idle:after{background:var(--a)}.locked:after{background:var(--r)}.dt{display:flex;justify-content:space-between}.robot{width:52px;height:52px;border:1px solid #3a4a61;border-radius:14px;display:grid;place-items:center;font-size:24px}.badge{font-size:9px;font-weight:900;border-radius:999px;padding:5px 7px;height:max-content}.badge.working{background:#103022;color:#8ef0b7}.badge.idle{background:#352a12;color:#ffd57d}.badge.locked{background:#35181b;color:#ff9a9a}.an{font-weight:900;font-size:17px;margin-top:8px}.role{font-size:11px;color:var(--m)}.act{font-size:12px;color:#c3ceda;min-height:35px;margin-top:8px}.meter{height:5px;background:#182332;border-radius:99px;margin-top:8px;overflow:hidden}.meter span{display:block;width:82%;height:100%;background:var(--c)}.locked .meter span{width:14%;background:var(--r)}.idle .meter span{width:38%;background:var(--a)}.btn{border:1px solid #314257;background:#111a26;color:#dbe5ef;border-radius:9px;padding:8px 10px;font-weight:800;font-size:11px;cursor:pointer}.primary{border-color:#2b7b5b;background:#10291f;color:#a8efc6}.danger{border-color:#71373b;background:#281417;color:#ffb2b2}.actions{display:flex;gap:7px;flex-wrap:wrap;margin-top:9px}.feed{padding:8px 16px}.event{padding:10px 0;border-bottom:1px solid #1d2734;font-size:12px}.event small{float:right;color:var(--m)}.card{padding:16px}.grid2{display:grid;grid-template-columns:repeat(2,1fr);gap:14px}.card h3{margin:0 0 6px}.form{display:grid;gap:10px;margin-top:12px}.input,.select,.textarea{width:100%;background:#080e15;color:#eef4fb;border:1px solid #304157;border-radius:9px;padding:10px;font:inherit}.textarea{min-height:90px}.tag{display:inline-block;padding:5px 7px;margin:6px 5px 0 0;border:1px solid #2c3c51;border-radius:999px;background:#111e2c;color:#b9c8d9;font-size:10px}.notice{padding:11px;border:1px solid #2a3c51;background:#101b28;border-radius:10px;color:#b9c7d6;font-size:12px}.tablewrap{overflow:auto;margin-top:12px}.table{width:100%;border-collapse:collapse}.table th,.table td{padding:10px;border-bottom:1px solid #202b3a;text-align:left;font-size:12px;vertical-align:top}.table th{font-size:10px;color:#8fa0b4;text-transform:uppercase}.chat{height:440px;display:flex;flex-direction:column}.chatlog{flex:1;overflow:auto;padding:12px}.msg{max-width:88%;padding:10px;border:1px solid var(--l);border-radius:11px;margin-bottom:9px;font-size:12px}.owner{margin-left:auto;background:#102433;border-color:#25475e}.who{font-size:9px;font-weight:900;color:var(--m);text-transform:uppercase;margin-bottom:3px}.chatform{display:flex;gap:7px;border-top:1px solid var(--l);padding:10px}.modal{position:fixed;inset:0;background:#000b;display:none;align-items:center;justify-content:center;padding:18px}.modal.open{display:flex}.modalbox{width:min(520px,100%);background:var(--p);border:1px solid #33465d;border-radius:14px;padding:18px}@media(max-width:1000px){.layout{grid-template-columns:1fr}.metrics{grid-template-columns:repeat(2,1fr)}}@media(max-width:700px){.shell{padding:13px}.office,.grid2{grid-template-columns:1fr}.metrics{grid-template-columns:1fr 1fr}.top{flex-direction:column}.title{font-size:24px}}
</style></head><body><main class="shell"><header class="top"><div><div class="ey">Private AI Financial Office</div><div class="title">Command Center</div><div class="muted">Sala de trabalho dos agentes • supervisionada pelo Owner</div></div><div class="online"><span class="dot"></span>SISTEMA ONLINE</div></header><nav class="nav" id="nav"><button class="active" data-v="home">Visão geral</button><button data-v="broker">Corretora</button><button data-v="reports">Relatórios</button><button data-v="team">Gestão da equipa</button><button data-v="chief">Chefe</button><button data-v="gov">Governance</button></nav>
<section id="home" class="view active"><div class="metrics"><div class="metric"><div class="label">ROBÔS NO ESCRITÓRIO</div><div class="value" id="total">—</div></div><div class="metric"><div class="label">A TRABALHAR</div><div class="value" id="working">—</div></div><div class="metric"><div class="label">EM ESPERA</div><div class="value" id="idle">—</div></div><div class="metric"><div class="label">BLOQUEADOS</div><div class="value" id="locked">—</div></div></div><div class="layout"><section class="panel"><div class="ph"><div><b>Sala de trabalho</b><div class="muted">Postos dos agentes</div></div><span class="muted" id="server">—</span></div><div class="office" id="office"></div></section><aside class="panel"><div class="ph"><b>Atividade</b><span class="muted">live</span></div><div class="feed" id="feed"></div></aside></div></section>
<section id="broker" class="view"><div class="grid2"><div class="card"><div style="display:flex;justify-content:space-between"><div><h3>Conectar corretora</h3><div class="muted">Conta, modo e permissões.</div></div><span class="tag" id="bstatus">NÃO CONECTADA</span></div><div class="notice" style="margin-top:12px">V0.5 não guarda chaves API reais. Primeiro configuramos o conector. A implementação de produção usará OAuth/API e armazenamento seguro de segredos.</div><form id="bform" class="form"><input class="input" id="provider" placeholder="Corretora / Exchange" required><input class="input" id="account" placeholder="Nome da conta" required><select class="select" id="mode"><option>PAPER</option><option>READ_ONLY</option><option>LIVE</option></select><label><input type="checkbox" value="market_data" checked> Dados de mercado</label><label><input type="checkbox" value="account_read"> Leitura de conta</label><label><input type="checkbox" value="trade"> Execução de ordens</label><button class="btn primary">Guardar configuração</button></form><div class="muted" id="bmsg"></div></div><div class="card"><h3>Política de conexão</h3><div class="muted">Começar por PAPER ou READ_ONLY. Execução LIVE deve exigir permissões mínimas, Risk, Governance, Owner e auditoria.</div><span class="tag">PAPER FIRST</span><span class="tag">LEAST PRIVILEGE</span><span class="tag">OWNER CONTROL</span><span class="tag">AUDIT TRAIL</span></div></div></section>
<section id="reports" class="view"><div class="card"><h3>Relatórios</h3><div class="muted">Factos, risco, pesquisa e diário de decisões.</div><div class="tablewrap"><table class="table"><thead><tr><th>Relatório</th><th>Período</th><th>Estado</th><th>Objetivo</th></tr></thead><tbody id="rbody"></tbody></table></div></div></section>
<section id="team" class="view"><div class="card"><div style="display:flex;justify-content:space-between;gap:10px"><div><h3>Gestão da equipa</h3><div class="muted">Vagas e skills de uma operação financeira de alto padrão.</div></div><button class="btn primary" id="newjob">+ Nova vaga</button></div><div class="tablewrap"><table class="table"><thead><tr><th>Função</th><th>Estado</th><th>Skills</th><th>Missão</th></tr></thead><tbody id="jbody"></tbody></table></div></div></section>
<section id="chief" class="view"><div class="card chat"><div style="display:flex;justify-content:space-between"><div><h3>Conversa com o Chefe</h3><div class="muted">Expectativas, ideias, prioridades e desenvolvimento da equipa.</div></div><span class="tag">ADVISOR</span></div><div class="chatlog" id="chatlog"></div><form class="chatform" id="chatform"><input class="input" id="chatinput" placeholder="Pergunte ao Chefe..." autocomplete="off"><button class="btn primary">Enviar</button></form></div></section>
<section id="gov" class="view"><div class="grid2"><div class="card"><h3>Governance</h3><div class="notice">Manager propõe. Owner decide. Permissões críticas e execução real exigem controlos adicionais.</div><p class="muted">Pedidos pendentes: <b id="pending">—</b></p><a class="btn" href="/docs">API Docs</a></div><div class="card"><h3>Mandato do escritório</h3><div class="muted">Processo orientado para acumulação de patrimônio com capital limitado: contribuições regulares, diversificação, custos, risco e disciplina. Não é garantia de retorno nem recomendação personalizada.</div><span class="tag">LONG TERM</span><span class="tag">RISK FIRST</span><span class="tag">SMALL CAPITAL</span></div></div></section></main>
<div class="modal" id="modal"><div class="modalbox"><h3>Nova vaga</h3><div class="muted">A vaga fica como DRAFT até governance.</div><div class="form"><input class="input" id="jt" placeholder="Título da função"><input class="input" id="js" placeholder="Skills, separadas por vírgula"><textarea class="textarea" id="jm" placeholder="Missão"></textarea></div><div class="actions" style="justify-content:flex-end"><button class="btn" id="cancel">Cancelar</button><button class="btn primary" id="save">Guardar</button></div></div></div>
<script>(function(){const $=s=>document.querySelector(s),esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#039;'}[c]));const icons={'agent-01':'◈','agent-02':'⌁','agent-03':'△','agent-04':'▣'};function view(v){document.querySelectorAll('.view').forEach(x=>x.classList.toggle('active',x.id===v));document.querySelectorAll('#nav button').forEach(x=>x.classList.toggle('active',x.dataset.v===v));if(v==='broker')loadBroker();if(v==='reports')loadReports();if(v==='team')loadJobs();if(v==='chief')loadChat()}$('#nav').onclick=e=>{const b=e.target.closest('button');if(b)view(b.dataset.v)};async function refresh(){try{const d=await (await fetch('/dashboard/state',{cache:'no-store'})).json();$('#total').textContent=d.office.total_agents;$('#working').textContent=d.office.working;$('#idle').textContent=d.office.idle;$('#locked').textContent=d.office.locked;$('#pending').textContent=d.pending_requests;$('#server').textContent=new Date(d.server_time).toLocaleTimeString('pt-PT');$('#office').innerHTML=d.agents.map(a=>{const c=a.ui_status.toLowerCase(),lab={WORKING:'A TRABALHAR',IDLE:'EM ESPERA',LOCKED:'BLOQUEADO'}[a.ui_status];let ac=a.status==='DISABLED'?'<button class="btn primary actbtn" data-id="'+a.id+'">▶ Colocar a trabalhar</button>':a.id!=='agent-01'?'<button class="btn danger stopbtn" data-id="'+a.id+'">■ Parar agente</button>':'';return '<article class="desk '+c+'"><div class="dt"><div class="robot">'+(icons[a.id]||'◉')+'</div><span class="badge '+c+'">'+lab+'</span></div><div class="an">'+esc(a.name)+'</div><div class="role">'+esc(a.title||a.role)+' • '+a.id+'</div><div class="muted" style="margin-top:6px">'+esc(a.mission||a.description||'')+'</div><div class="act">'+esc(a.activity)+'</div><div class="meter"><span></span></div><div class="actions">'+ac+'</div></article>'}).join('');document.querySelectorAll('.actbtn').forEach(b=>b.onclick=()=>control(b.dataset.id,'activate'));document.querySelectorAll('.stopbtn').forEach(b=>b.onclick=()=>control(b.dataset.id,'deactivate'));$('#feed').innerHTML=d.events.map(e=>'<div class="event"><b>Owner control</b><small>'+new Date(e.time).toLocaleTimeString('pt-PT')+'</small><br>'+esc(e.event)+' • '+esc(e.agent_id)+'</div>').join('')+d.agents.map(a=>'<div class="event"><b>'+esc(a.name)+'</b><small>'+new Date(a.last_tick).toLocaleTimeString('pt-PT')+'</small><br>'+esc(a.activity)+'</div>').join('')}catch(e){$('#server').textContent='offline'}}async function control(id,action){const owner=prompt('Owner ID:','owner-001');if(!owner)return;const r=await fetch('/agents/'+id+'/'+action,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({owner_id:owner})});if(!r.ok){const d=await r.json();alert(d.detail||'Falha');return}refresh()}async function loadBroker(){const d=await (await fetch('/office/broker')).json();$('#bstatus').textContent=d.status==='NOT_CONNECTED'?'NÃO CONECTADA':d.mode+' • '+d.provider;$('#provider').value=d.provider||'';$('#account').value=d.account_label||'';$('#mode').value=d.mode||'PAPER'}$('#bform').onsubmit=async e=>{e.preventDefault();const permissions=[...document.querySelectorAll('#bform input[type=checkbox]:checked')].map(x=>x.value);const d=await (await fetch('/office/broker/configure',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({provider:$('#provider').value,account_label:$('#account').value,mode:$('#mode').value,permissions})})).json();$('#bstatus').textContent=d.mode+' • '+d.provider;$('#bmsg').textContent='Configuração guardada; nenhum segredo foi persistido.'};async function loadReports(){const d=await (await fetch('/office/reports')).json();$('#rbody').innerHTML=d.reports.map(x=>'<tr><td><b>'+esc(x.title)+'</b></td><td>'+x.period+'</td><td>'+x.status+'</td><td>'+esc(x.summary)+'</td></tr>').join('')}async function loadJobs(){const d=await (await fetch('/office/jobs')).json();$('#jbody').innerHTML=d.jobs.map(x=>'<tr><td><b>'+esc(x.title)+'</b></td><td>'+x.status+'</td><td>'+x.skills.map(s=>'<span class="tag">'+esc(s)+'</span>').join('')+'</td><td>'+esc(x.mission)+'</td></tr>').join('')}function addMsg(r,t){const d=document.createElement('div');d.className='msg '+r;d.innerHTML='<div class="who">'+(r==='owner'?'Owner':'Chefe')+'</div>'+esc(t);$('#chatlog').appendChild(d);$('#chatlog').scrollTop=$('#chatlog').scrollHeight}async function loadChat(){const d=await (await fetch('/office/chat')).json();$('#chatlog').innerHTML='';d.messages.forEach(m=>addMsg(m.role,m.message))}$('#chatform').onsubmit=async e=>{e.preventDefault();const t=$('#chatinput').value.trim();if(!t)return;$('#chatinput').value='';const d=await (await fetch('/office/chat',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({message:t})})).json();$('#chatlog').innerHTML='';d.messages.forEach(m=>addMsg(m.role,m.message))};$('#newjob').onclick=()=>$('#modal').classList.add('open');$('#cancel').onclick=()=>$('#modal').classList.remove('open');$('#save').onclick=()=>{const t=$('#jt').value.trim(),s=$('#js').value.split(',').map(x=>x.trim()).filter(Boolean),m=$('#jm').value.trim();if(!t||!s.length||!m)return alert('Preencha os campos.');$('#jbody').insertAdjacentHTML('afterbegin','<tr><td><b>'+esc(t)+'</b></td><td>DRAFT</td><td>'+s.map(x=>'<span class="tag">'+esc(x)+'</span>').join('')+'</td><td>'+esc(m)+'</td></tr>');$('#modal').classList.remove('open');['jt','js','jm'].forEach(id=>$('#'+id).value='')};refresh();loadChat();setInterval(refresh,3000)})();</script></body></html>'''
